"""Archive primary plus reviewer local roles for the live startup chain."""
import hashlib,json,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
read=lambda p:json.loads(p.read_text())
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    primary=Path(read(ROOT/'verification/easy-startup-loading-movie-world-scope-pointer.json')['directory']);reviewer=Path(read(ROOT/'verification/local-startup-chain-reviewer-pointer.json')['directory']);a=read(primary/'protocol.json');b=read(reviewer/'protocol.json');item=a['results'][0]
    assert a['status']==b['status']=='completed_pending_coordinator_review'and not item['quality_flags']and not b['quality_flags']
    assert all(p['stats']['stopReason']=='eosFound'for p in item['prediction_stats']+b['prediction_stats'])
    assert item['words']<160 and b['words']<220 and b['same_weights_as_primary']and not b['independent_code_verification']
    assert all(t in item['answer']for t in ['captures are removed','26 handoffs/13 ticks','187-frame/125-enqueue','12 later world','4000/global boot'])
    assert all(t in b['response']for t in ['task quiescence','GPU completion','Two fresh Native/C profiles','captures are removed','native Chat'])
    corrected=b['response'].split('Corrected Answer:',1)[1].strip();assert len(corrected.split())<160
    cp=read(ROOT/'verification/startup-loading-movie-world-checkpoint.json');assert not cp['earlier_startup_capture_supplied']and cp['source_startup_to_loading_movie_world_connected']and cp['verified_profiles']==2
    now=datetime.now(timezone.utc);out=ROOT/'verification/live-startup-two-role-inference-review'/now.strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
    files=[primary/'protocol.json',primary/'prompts-and-responses.txt',reviewer/'protocol.json',reviewer/'prompts-and-responses.txt',ROOT/'scripts/test_startup_loading_movie_world_scope.py',ROOT/'scripts/review_startup_loading_movie_world_local_answer.py',ROOT/'scripts/check_startup_loading_movie_world_mcp.py',ROOT/'verification/startup-loading-movie-world-MCP-check.json',ROOT/'verification/startup-loading-movie-world-checkpoint.json',ROOT/'chat_tools.py',Path(__file__)]
    manifest=[]
    for i,p in enumerate(files):
        target=out/f'{i:02d}-{p.name}';shutil.copy2(p,target);assert sha(p)==sha(target);manifest.append(dict(source=str(p),snapshot=str(target),sha256=sha(p)))
    review=dict(status='primary_core_scope_accepted_reviewer_principal_provider_repair_accepted',recorded_at=now.isoformat(),directory=str(out),model=a['model'],interface=a['interface'],roles=[dict(role='game_assistant',words=item['words'],seconds=item['seconds'],semantic_review='Correct capture removal/livechain/counts/boot limits; principal provider inventory omitted taskquiescence/synchronousGPU completion and did not explicitly name two profiles.'),dict(role='game_evidence_reviewer',words=b['words'],seconds=b['seconds'],semantic_review='Correctly identifies the omitted principal categories and two-profile wording, repairs concise answer with remaining providers/limits. GPUcompletion qualifier is not explicit in corrected wording; exact synchronous poll model remains in source checkpoint.')],same_model_weights_for_roles=True,sequential_one_worker=True,independent_code_verification=False,code_verification_source=cp['audit'],complete_device_timing_provider_inventory=False,native_Chat_verified=False,new_training=False,model_defaults_changed=False,whole_goal_complete=False,files=manifest)
    save(out/'review.json',review);save(ROOT/'verification/live-startup-two-role-inference-review.json',review)
    transcript='COORDINATOR\n'+cp['implementation_authorship']+'\nSource comparisons are Native/C; local roles review wording from installed evidence.\n\nPRIMARY ROLE EXACT PROMPTS/TOOL CALLS/RESPONSES\n'+(primary/'prompts-and-responses.txt').read_text()+'\n\nREVIEWER ROLE EXACT PROMPTS/TOOL CALLS/RESPONSES\n'+(reviewer/'prompts-and-responses.txt').read_text();(out/'who-prompts-and-responses.txt').write_text(transcript)
    note='LATEST LOCAL WORKFLOW — LIVE STARTUP CHAIN, PRIMARY + REVIEWER\n'+now.isoformat()+'\n\nEveryday27B6bit/32K/one-worker model. Primary:102words/21.45seconds, correct capture removal/livechain/core limits, omitted quiescence/GPUcompletion. Same-weight reviewer:133words/18.04seconds, caught those omissions and two-profile wording, repaired principal provider summary. Both roles used one evidence tool call and ended naturally with no mechanical flags. Coordinator checked exact answers against source comparison. Complete timing/device details remain in checkpoint; no general reliability/independent model verification/nativeChat/training/default changes claimed.\n\nPRIMARY EXACT ANSWER\n'+item['answer']+'\n\nREVIEWER EXACT RESPONSE\n'+b['response']+'\n\nWHO, EXACT SYSTEM/USER PROMPTS, TOOL CALLS AND RESPONSES\n'+str(out/'who-prompts-and-responses.txt')+'\n\nREVIEW\n'+str(out/'review.json')+'\n\n'
    p=ROOT/'CURRENT LOCAL INFERENCE.txt';p.write_text(note+p.read_text())
    p=ROOT/'START HERE.txt';p.write_text('Latest:earlierstartup/readymerchant captures removed from connectedtest. Two fresh Native/C profiles run sourceDD40/scheduledstartup/healthsleep (26handoffs/13systemticks), live loading/merchantcreation,187-frame125-enqueue movie and12world/NPC/renderercycles.18asset transfers1108650bytes; no intermediateRAMrestore/processorreset. FrozenRAM/processor-setup/controlledinput/task/clock/CD/BIOS/blitter/GPUcompletion providers remain; fullboot/playability unverified.\nLocalworkflow:primary21.45seconds plus same-model reviewer18.04seconds; reviewer caught missing quiescence/GPUcompletion/two-profile wording and repaired principal summary. SDK, notverifiednativeChat; no newtraining/defaultchanges.\nAudit: '+str(out)+'\nPreview: '+cp['geometry_plane_preview']['image_path']+'\n\n'+p.read_text())
    (out/'readable-results.txt').write_text(note);print(json.dumps(dict(status=review['status'],directory=str(out),primary_seconds=item['seconds'],reviewer_seconds=b['seconds'])))
if __name__=='__main__':main()
